    def computeControl(self, x, t):
        #Chooses between healthy QSF and QSF_fault based on time.

        if t < self.t_switch:
            return self.compute_QSF(x, t)
        else:
            return self.compute_QSF_fault(x, t)

    def CalcOutput(self, context, output):
        x = self.get_input_port(0).Eval(context)
        t = context.get_time()

        f_W, tau, R, u__t = self.computeControl(x, t)
        #f_W, tau, R = self.compute_QSF(x, t)

        # Map body-frame tau to world-frame torque, or keep zero if you
        # only want translational control.
        tau_W = R @ tau


        # Build the force container
        force_container = ExternallyAppliedSpatialForce()

        # (1) body_index
        force_container.body_index = self.body_index

        # (2) p_BoBq_B: Apply at CoM (body origin)
        force_container.p_BoBq_B = np.zeros(3)

        # (3) F_Bq_W: spatial force (tau, f)
        force_container.F_Bq_W = SpatialForce(
            tau=tau_W.reshape(3, 1),
            f=f_W.reshape(3, 1),
        )

        output.set_value([force_container])

    def CalcForceOutput(self, context, output):
        x = self.get_input_port(0).Eval(context)
        t = context.get_time()

        f, _, _, _ = self.computeControl(x, t)
        output.SetFromVector(f)

    def CalcTauOutput(self, context, output):
        """
        Outputs the body-frame torque tau as a 3D vector
        for logging / analysis.
        """
        x = self.get_input_port(0).Eval(context)
        t = context.get_time()

        _, tau, _, _ = self.computeControl(x, t)
        output.SetFromVector(tau)

    def CalcThrustOutput(self, context, output):
        """
        Outputs the thrust
        for logging / analysis.
        """
        x = self.get_input_port(0).Eval(context)
        t = context.get_time()

        _, _, _, u__t = self.computeControl(x, t)
        output.SetFromVector([u__t])

